arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history?token=<TOKEN>&channel=C_LAUNCH&limit=200" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print(d); sys.exit()
for m in d['messages']:
    reacts = m.get('reactions')
    if reacts:
        names = [f\"{r['name']}({len(r['users'])}:{','.join(r['users'])})\" for r in reacts]
        print(m['ts'], m.get('user'), repr(m.get('text'))[:120], 'REACTS:', names)
    else:
        print(m['ts'], m.get('user'), repr(m.get('text'))[:120])
"

